const fs = require('fs');
const cp = require('child_process');

const obj = [
'v 0 0 0','v 1 0 0','v 1 1 0','v 0 1 0',
'v 0 0 1','v 1 0 1','v 1 1 1','v 0 1 1',
'f 1 4 3','f 1 2 3','f 5 6 7','f 5 8 7','f 1 2 6','f 1 6 5',
'f 2 3 7','f 2 7 6','f 3 4 8','f 3 7 8','f 4 1 5','f 4 5 8'
].join('\n') + '\n';
fs.writeFileSync('in.obj', obj);

fs.writeFileSync('fix.js', `const fs = require('fs');
const lines = fs.readFileSync('in.obj', 'utf8').split(/\\r?\\n/);
const verts = [];
const faces = [];
for (const line of lines) {
  const t = line.trim();
  if (!t) continue;
  const p = t.split(/\\s+/);
  if (p[0] === 'v') verts.push(p.slice(1).map(Number));
  else if (p[0] === 'f') faces.push(p.slice(1).map(Number).map(n => n - 1));
}
const c = [0, 0, 0];
for (const v of verts) for (let i = 0; i < 3; i++) c[i] += v[i];
for (let i = 0; i < 3; i++) c[i] /= verts.length;
const sub = (a, b) => [a[0]-b[0], a[1]-b[1], a[2]-b[2]];
let inverted = 0;
const outFaces = faces.map(f => {
  const a = verts[f[0]], b = verts[f[1]], d = verts[f[2]];
  const e1 = sub(b, a), e2 = sub(d, a);
  const n = [e1[1]*e2[2]-e1[2]*e2[1], e1[2]*e2[0]-e1[0]*e2[2], e1[0]*e2[1]-e1[1]*e2[0]];
  const g = [(a[0]+b[0]+d[0])/3, (a[1]+b[1]+d[1])/3, (a[2]+b[2]+d[2])/3];
  const r = sub(g, c);
  const dot = n[0]*r[0] + n[1]*r[1] + n[2]*r[2];
  if (dot < 0) { inverted++; return [f[0], f[2], f[1]]; }
  return f;
});
const outLines = [];
for (const line of lines) {
  const t = line.trim();
  if (!t) continue;
  if (t.split(/\\s+/)[0] === 'v') outLines.push(line);
}
for (const f of outFaces) outLines.push('f ' + f.map(i => i + 1).join(' '));
fs.writeFileSync('fixed.obj', outLines.join('\\n') + '\\n');
console.log(JSON.stringify({ total: faces.length, inverted, fixed: inverted }));
`);

const out = cp.execFileSync(process.execPath, ['fix.js'], { encoding: 'utf8' });
process.stdout.write(out);
console.log('DONE: in.obj + fix.js written, fixed.obj produced ' + out.trim());

const fs = require('fs'), cp = require('child_process');

const SCRIPT = [
  'const fs = require("fs");',
  'const path = require("path");',
  'const file = path.join(__dirname, "config.json");',
  'let raw;',
  'try { raw = fs.readFileSync(file, "utf8"); } catch (e) { process.stderr.write("MISSING\\n"); process.exit(1); }',
  'let data;',
  'try { data = JSON.parse(raw); } catch (e) { process.stderr.write("INVALID\\n"); process.exit(1); }',
  'if (data === null || typeof data !== "object" || Array.isArray(data)) { process.stderr.write("INVALID\\n"); process.exit(1); }',
  'const out = new Map();',
  'for (const k of Object.keys(data)) out.set(k, data[k]);',
  'out.set("enabled", true);',
  'out.set("version", 2);',
  'fs.writeFileSync(file, JSON.stringify(Object.fromEntries(out)) + "\\n");',
  'process.stdout.write("OK " + [...out.keys()].join(",") + "\\n");',
].join('\n');

